// Pseudo-test outline for region-scoped booking with idempotent payment
describe('Regional booking E2E', () => {
  it('handles regional outage and retries with idempotency', async () => {
    seedRegion('us-east');
    simulateOutage('us-west', 'payment');
    const id = 'ide-12345';
    await initiateBooking({ region: 'us-east', idempotencyKey: id });
    await verifyLedgerEvents({ region: 'us-east', id });
